const errors=[];
page.on('pageerror',e=>errors.push(e.message));
await page.goto('http://localhost:5174');
await page.getByLabel('Название заметки').waitFor();
await page.screenshot({path:'/tmp/listva-desktop.png',fullPage:true});
await page.getByLabel('Содержание',{exact:true}).fill('## Проверка\\n\\n**Жирный** и *курсив*\\n\\n- Пункт\\n\\n> Цитата\\n\\n- [x] Готово');
await page.locator('.markdown-preview h2').filter({hasText:'Проверка'}).waitFor();
if(await page.locator('.markdown-preview strong').textContent() "'!== '"'Жирный') throw Error('Bold render failed');
if(await page.locator('.markdown-preview input[type=checkbox]:checked').count() "'!== 1) throw Error('"'Task list failed');
await page.getByRole('button',{name:'Жирный',exact:true}).click();
if("'!(await page.locator('"'textarea').inputValue()).includes('**текст**')) throw Error('Toolbar failed');
await page.getByRole('button',{name:'Просмотр',exact:true}).click();
if(await page.locator('textarea').count()) throw Error('Preview mode failed');
await page.getByRole('button',{name:'Рядом',exact:true}).click();
await page.getByRole('button',{name:'Сохранить заметку',exact:true}).click();
const stored=await page.locator('textarea').inputValue();
await page.reload();
if(await page.locator('textarea').inputValue() "'!== stored) throw Error('"'Persistence failed');
await page.getByRole('button',{name:'Подсказка по Markdown',exact:true}).click();
await page.getByRole('dialog').waitFor();
await page.keyboard.press('Escape');
if(await page.getByRole('dialog').count()) throw Error('Dialog did not close');
await page.locator('textarea').fill('<script>alert(1)</script>\\n\\n[bad](javascript:alert(1))');
if(await page.locator('.markdown-preview script').count()) throw Error('Unsafe HTML rendered');
if(await page.locator('.markdown-preview a').getAttribute('href')?.startsWith('javascript:')) throw Error('Unsafe URL');
await page.setViewportSize({width:390,height:844});
await page.evaluate(()=>localStorage.clear());
page.on('dialog',d=>d.accept());
await page.reload();
await page.screenshot({path:'/tmp/listva-mobile.png',fullPage:true});
const overflow=await page.evaluate(()=>document.documentElement.scrollWidth > innerWidth);
if(overflow) throw Error('Mobile horizontal overflow');
if(errors.length) throw Error(errors.join('\\n'));
console.log('PASS: live Markdown, task lists, toolbar, view modes, saving and reload, help dialog, HTML safety, mobile layout. No page errors.');
await browser.close();
EOF"

